const item = $input.item.json;

// Im Erstlauf bleibt der Diagnose-basierte Positionspool unveraendert.
// In einer Request-Changes-Folgerunde ist die vom Reviewer bereits editierte
// Position jedoch Teil des verbindlichen Ausgangsstands und muss deshalb
// weiterhin zulaessig bleiben, auch wenn sie ausserhalb des urspruenglich
// aus diagnosisCategory abgeleiteten Pools liegt.
const DEFENSIVE_POSITIONS = ['Innenverteidiger', 'Linksverteidiger', 'Rechtsverteidiger', 'Defensives Mittelfeld'];
const ATTACKING_POSITIONS = ['Offensives Mittelfeld', 'Linksaußen', 'Mittelstürmer'];
const ALL_POSITIONS = ['Innenverteidiger', 'Linksverteidiger', 'Rechtsverteidiger', 'Defensives Mittelfeld', 'Zentrales Mittelfeld', 'Offensives Mittelfeld', 'Linksaußen', 'Mittelstürmer'];

const diagnosisCategory = (item.teamDiagnosis && item.teamDiagnosis.diagnosisCategory) || 'no_data';
let allowedPositions = diagnosisCategory === 'defensive'
  ? [...DEFENSIVE_POSITIONS]
  : diagnosisCategory === 'offensive'
    ? [...ATTACKING_POSITIONS]
    : [...ALL_POSITIONS];

const reviewedPosition = item.reviewDecision === 'Request Changes' && item.playerProfile
  ? item.playerProfile.position
  : null;
if (typeof reviewedPosition === 'string' && reviewedPosition.trim() && !allowedPositions.includes(reviewedPosition.trim())) {
  allowedPositions.push(reviewedPosition.trim());
}

return [{ json: { ...item, allowedPositions } }];

