const item = $input.item.json;
const rawError = item && item.error;
const rawMessage = typeof rawError === 'string'
  ? rawError
  : (rawError && rawError.message) ? rawError.message : 'Unbekannter Fehler';

// Eigene Kopie dieser Subworkflow-Datei (technische Utility-Node, siehe
// n8n/README.md): ergaenzt zusaetzlich valid: false, damit der konsolidierte
// Phase-Ergebnis-Vertrag (siehe 'Scouting Brief erstellen: Ergebnis') auch
// auf dem Fehlerpfad korrekt befuellt ist.
return [{
  json: {
    ...item,
    valid: false,
    errorMessage: 'Bei der Kommunikation mit dem lokalen Ollama-Modell ist ein Fehler aufgetreten. Bitte versuchen Sie es später erneut.\n\nDetails: ' + rawMessage
  }
}];

const llmResult = $json.output ?? $json;
const original = $('Spielerprofil: Positionspool ermitteln').first().json;
const isRevision = original.reviewDecision === 'Request Changes' && original.playerProfile && typeof original.playerProfile === 'object';
const baseline = isRevision ? original.playerProfile : {};

const resolved = (field) => {
  const value = llmResult[field];
  if (isRevision && (value === null || value === undefined)) return baseline[field];
  return value;
};

const playerProfile = {
  ...baseline,
  simulated: false,
  position: resolved('position'),
  role: resolved('role'),
  weightedCriteria: resolved('weightedCriteria'),
  constraints: resolved('constraints'),
  reasoning: resolved('reasoning')
};

if (!playerProfile.position) {
  throw new Error('Spielerprofil enthaelt nach Merge keine position. Input: ' + JSON.stringify($json));
}
if (!playerProfile.role) {
  throw new Error('Spielerprofil enthaelt nach Merge keine role. Input: ' + JSON.stringify($json));
}

const aiReviewOutcome = ['Approve', 'Request Changes', 'Reject'].includes(llmResult.reviewOutcome) ? llmResult.reviewOutcome : 'Approve';
const aiReviewFeedback = typeof llmResult.reviewFeedback === 'string' ? llmResult.reviewFeedback : '';

return {
  json: {
    ...original,
    playerProfile,
    aiReviewOutcome,
    aiReviewFeedback
  }
};

const item = $input.item.json;
const p = item.playerProfile;
const errors = [];

if (!p || typeof p !== 'object') {
  errors.push('playerProfile fehlt oder ist kein Objekt.');
} else {
  if (!p.position) errors.push('playerProfile.position fehlt.');
  if (!p.role) errors.push('playerProfile.role fehlt.');
  if (!p.reasoning) errors.push('playerProfile.reasoning fehlt.');
  if (!Array.isArray(p.weightedCriteria) || p.weightedCriteria.length === 0) {
    errors.push('playerProfile.weightedCriteria fehlt oder ist leer.');
  } else if (p.weightedCriteria.some((c) => !c.criterion || typeof c.weight !== 'number')) {
    errors.push('playerProfile.weightedCriteria enthaelt einen Eintrag ohne criterion oder numerisches weight.');
  }
  if (!Array.isArray(p.constraints)) {
    errors.push('playerProfile.constraints fehlt oder ist kein Array.');
  } else if (p.constraints.some((c) => !c || !['age', 'marketValueMEUR'].includes(c.field) || !['max', 'min'].includes(c.operator) || typeof c.value !== 'number' || !Number.isFinite(c.value))) {
    errors.push('playerProfile.constraints enthaelt einen Eintrag ohne gueltiges field/operator/numerisches value.');
  }

  if (p && p.position) {
    const allowedPositions = Array.isArray(item.allowedPositions) ? item.allowedPositions : [];
    if (allowedPositions.length > 0 && !allowedPositions.includes(p.position)) {
      errors.push(`playerProfile.position ('${p.position}') ist nicht im vorbereiteten Positionspool enthalten (erlaubt: ${allowedPositions.join(', ')}).`);
    }
  }
}

const valid = errors.length === 0;
return [{
  json: {
    ...item,
    valid,
    errorMessage: valid ? undefined : 'Das Spielerprofil ist ungueltig und wird nicht fuer die Spielersuche verwendet.\n\n' + errors.join('\n')
  }
}];

const MAX_REVIEW_ROUNDS = 3;
const item = $input.item.json;
const priorBrief = item.scoutingBrief;
const feedbackHistory = Array.isArray(priorBrief && priorBrief.feedbackHistory)
  ? [...priorBrief.feedbackHistory]
  : [];

if (item.reviewDecision === 'Request Changes' && priorBrief) {
  feedbackHistory.push({ round: priorBrief.reviewRound, feedback: item.reviewFeedback || '' });
}

const teamDiagnosis = item.teamDiagnosis || {};
const playerProfile = item.playerProfile || {};

const scoutingBrief = {
  problem: teamDiagnosis.mainProblem,
  targetPosition: playerProfile.position,
  role: playerProfile.role,
  reasoning: playerProfile.reasoning,
  weightedCriteria: playerProfile.weightedCriteria,
  constraints: playerProfile.constraints,
  uncertainties: Array.isArray(teamDiagnosis.uncertainties) ? teamDiagnosis.uncertainties : [],
  reviewOutcome: item.aiReviewOutcome,
  reviewFeedback: item.aiReviewFeedback,
  reviewRound: feedbackHistory.length + 1,
  maxReviewRounds: MAX_REVIEW_ROUNDS,
  feedbackHistory
};

return [{ json: { ...item, scoutingBrief } }];

const item = $input.item.json;
const b = item.scoutingBrief;
const errors = [];

if (!b || typeof b !== 'object') {
  errors.push('scoutingBrief fehlt oder ist kein Objekt.');
} else {
  if (!b.problem) errors.push('scoutingBrief.problem fehlt.');
  if (!b.targetPosition) errors.push('scoutingBrief.targetPosition fehlt.');
  if (!b.role) errors.push('scoutingBrief.role fehlt.');
  if (!b.reasoning) errors.push('scoutingBrief.reasoning fehlt.');
  if (!Array.isArray(b.weightedCriteria) || b.weightedCriteria.length === 0) errors.push('scoutingBrief.weightedCriteria fehlt oder ist leer.');
  if (!Array.isArray(b.constraints)) errors.push('scoutingBrief.constraints fehlt oder ist kein Array.');
  if (!Array.isArray(b.uncertainties)) errors.push('scoutingBrief.uncertainties fehlt oder ist kein Array.');
  if (!['Approve', 'Request Changes', 'Reject'].includes(b.reviewOutcome)) errors.push('scoutingBrief.reviewOutcome ist ungueltig.');
  if (typeof b.reviewFeedback !== 'string') errors.push('scoutingBrief.reviewFeedback fehlt oder ist kein String.');
  if (b.reviewOutcome === 'Request Changes' && !b.reviewFeedback.trim()) errors.push('scoutingBrief.reviewFeedback darf bei Request Changes nicht leer sein.');
}

const valid = errors.length === 0;
return [{
  json: {
    ...item,
    valid,
    errorMessage: valid ? undefined : 'Das Scouting Brief ist ungueltig und wird nicht zur Freigabe vorgelegt.\n\n' + errors.join('\n')
  }
}];

const item = $input.item.json;
if (item.valid === false) {
  throw new Error('[SCOUTING_BRIEF] ' + (item.errorMessage || 'Scouting Brief erstellen ist fehlgeschlagen.'));
}
return [{ json: { ...item, status: 'success' } }];
